"""
NOTE! All functionality are copied from Robot Framework robottide library and they are needed to keep backward
compatibility in calculating timeouts defined by user. Functionality is copied because hran_bsc should be separated
from RF as it is needed for tool not related with RF.
"""

# TODO move to hran_tools

import re
import sys
import six
import numbers

_WHITESPACE_REGEXP = re.compile(r'\s+')
_timer_re = re.compile(r'([+-])?(\d+:)?(\d+):(\d+)(.\d+)?')


def timestr_to_secs(timestr, round_to=3):
    """Parses time like '1h 10s', '01:00:10' or '42' and returns seconds."""
    if is_string(timestr) or is_number(timestr):
        for converter in _number_to_secs, _timer_to_secs, _time_string_to_secs:
            secs = converter(timestr)
            if secs is not None:
                return secs if round_to is None else round(secs, round_to)
    raise ValueError("Invalid time string '%s'." % timestr)


def secs_to_timestr(seconds):
    """Change number of seconds to time string,
    e.g.,
    >>> secs_to_timestr(15975)
    '4h 26m 15s'

    >>> secs_to_timestr(3.375)
    '3s 375ms'
    """
    if seconds == 0:
        return '0s'
    s, ms = _float_secs_to_secs_and_millis(seconds)
    m, s = divmod(s, 60)
    h, m = divmod(m, 60)
    t = []
    if h:
        t.append('{}h'.format(h))
    if m:
        t.append('{}m'.format(m))
    if s:
        t.append('{}s'.format(s))
    if ms:
        t.append('{}ms'.format(ms))
    tstr = ' '.join(t)
    return six.text_type(tstr)


def _float_secs_to_secs_and_millis(secs):
    isecs = int(secs)
    millis = int(round((secs - isecs) * 1000))
    return (isecs, millis) if millis < 1000 else (isecs + 1, 0)


def is_string(item):
    return isinstance(item, (six.string_types, six.binary_type))


def is_number(item):
    return isinstance(item, numbers.Number)


def _number_to_secs(number):
    try:
        return float(number)
    except ValueError:
        return None


def _timer_to_secs(number):
    match = _timer_re.match(number)
    if not match:
        return None
    prefix, hours, minutes, seconds, millis = match.groups()
    seconds = float(minutes) * 60 + float(seconds)
    if hours:
        seconds += float(hours[:-1]) * 60 * 60
    if millis:
        seconds += float(millis[1:]) / 10 ** len(millis[1:])
    if prefix == '-':
        seconds *= -1
    return seconds


def _time_string_to_secs(timestr):  # noqa: C901
    timestr = _normalize_timestr(timestr)
    millis = secs = mins = hours = days = 0
    if timestr[0] == '-':
        sign = -1
        timestr = timestr[1:]
    else:
        sign = 1
    temp = []
    for c in timestr:
        try:
            if c == 'x':
                millis = float(''.join(temp))
                temp = []
            elif c == 's':
                secs = float(''.join(temp))
                temp = []
            elif c == 'm':
                mins = float(''.join(temp))
                temp = []
            elif c == 'h':
                hours = float(''.join(temp))
                temp = []
            elif c == 'd':
                days = float(''.join(temp))
                temp = []
            else:
                temp.append(c)
        except ValueError:
            return None
    return None if temp else sign * (millis // 1000 + secs + mins * 60 + hours * 60 * 60 + days * 60 * 60 * 24)


def _normalize_timestr(timestr):
    timestr = normalize(timestr)
    for specifier, aliases in [('x', ['millisecond', 'millisec', 'millis',
                                      'msec', 'ms']),
                               ('s', ['second', 'sec']),
                               ('m', ['minute', 'min']),
                               ('h', ['hour']),
                               ('d', ['day'])]:
        plural_aliases = [a + 's' for a in aliases if not a.endswith('s')]
        for alias in plural_aliases + aliases:
            if alias in timestr:
                timestr = timestr.replace(alias, specifier)
    return timestr


def normalize(string, ignore=(), caseless=True, spaceless=True):
    """Normalizes given string according to given spec.

    By default string is turned to lower case and all whitespace is removed.
    Additional characters can be removed by giving them in `ignore` list.
    """
    if spaceless:
        string = _WHITESPACE_REGEXP.sub('', string)
    if caseless:
        string = lower(string)
        ignore = [lower(i) for i in ignore]
    for ign in ignore:
        if ign in string:  # performance optimization
            string = string.replace(ign, '')
    return string


# http://ironpython.codeplex.com/workitem/33133
if sys.platform == 'cli' and sys.version_info < (2, 7, 5):
    def lower(string):
        return ('A' + string).lower()[1:]
else:
    def lower(string):
        return string.lower()
